/* === MODO ESTUDIO - Colores optimizados para aprendizaje === */
/* Paleta basada en investigación de UX para reducir fatiga visual */

/* Variables del Modo Estudio */
html[data-study-mode="true"] {
  /* Fondo beige suave - reduce brillo y fatiga visual */
  --color-bg-primary: #f8f4ec;
  --color-bg-secondary: #f0ece4;
  --color-bg-tertiary: #e8e4dc;

  /* Texto gris azulado - menos agresivo que negro puro */
  --color-text-primary: #2c3e50;
  --color-text-secondary: #5a6c7d;
  --color-text-muted: #8e9eab;

  /* Acentos atenuados - tonos serenos */
  --color-accent-primary: #7c9082; /* Verde oliva apagado */
  --color-accent-secondary: #b8a99a; /* Terracota suave */
  --color-accent-tertiary: #a8b5c2; /* Azul grisáceo */

  /* Resaltado para conceptos clave */
  --color-highlight: #fffacd; /* Amarillo pastel */
  --color-highlight-border: #e6d9a0;

  /* Bordes suaves */
  --color-border: #d4cfc7;
  --color-border-strong: #b8b3ab;

  /* Sombras sutiles */
  --shadow-sm: 0 1px 2px rgba(44, 62, 80, 0.05);
  --shadow-md: 0 2px 4px rgba(44, 62, 80, 0.08);
  --shadow-lg: 0 4px 8px rgba(44, 62, 80, 0.12);

  /* Tipografía optimizada para lectura */
  font-size: 17px;
  line-height: 1.7;
  letter-spacing: 0.01em;
}

/* Regla de Lectura - Enfoca un párrafo a la vez */
.reading-ruler {
  position: fixed;
  left: 0;
  right: 0;
  height: 120px;
  background: linear-gradient(
    to bottom,
    transparent 0%,
    rgba(248, 244, 236, 0.3) 20%,
    rgba(248, 244, 236, 0.95) 40%,
    rgba(248, 244, 236, 0.95) 60%,
    rgba(248, 244, 236, 0.3) 80%,
    transparent 100%
  );
  pointer-events: none;
  z-index: 9998;
  transition: top 0.3s ease;
}

.reading-ruler::before,
.reading-ruler::after {
  content: '';
  position: absolute;
  left: 0;
  right: 0;
  height: 1px;
  background: var(--color-border-strong);
}

.reading-ruler::before {
  top: 20%;
}

.reading-ruler::after {
  bottom: 20%;
}

/* Temporizador Pomodoro */
.pomodoro-widget {
  position: fixed;
  bottom: 80px;
  right: 20px;
  background: var(--color-bg-primary);
  border: 2px solid var(--color-border);
  border-radius: 12px;
  padding: 16px;
  box-shadow: var(--shadow-lg);
  z-index: 9997;
  min-width: 200px;
  font-family: 'Courier New', monospace;
}

.pomodoro-timer {
  font-size: 32px;
  font-weight: bold;
  text-align: center;
  color: var(--color-text-primary);
  margin-bottom: 12px;
}

.pomodoro-controls {
  display: flex;
  gap: 8px;
  justify-content: center;
}

.pomodoro-btn {
  padding: 6px 12px;
  border: 1px solid var(--color-border-strong);
  background: var(--color-bg-secondary);
  color: var(--color-text-primary);
  border-radius: 6px;
  cursor: pointer;
  font-size: 14px;
  transition: all 0.2s;
}

.pomodoro-btn:hover {
  background: var(--color-bg-tertiary);
}

.pomodoro-btn.active {
  background: var(--color-accent-primary);
  color: white;
  border-color: var(--color-accent-primary);
}

/* Tarjetas de Curso Mejoradas */
.course-card {
  background: var(--color-bg-primary);
  border: 1px solid var(--color-border);
  border-radius: 12px;
  padding: 20px;
  box-shadow: var(--shadow-sm);
  transition: all 0.3s ease;
  position: relative;
  overflow: hidden;
}

.course-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.course-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 4px;
  background: var(--color-accent-primary);
}

.course-card.certification::before {
  background: linear-gradient(90deg, var(--color-accent-primary), var(--color-accent-tertiary));
}

.course-badge {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 4px 10px;
  border-radius: 20px;
  font-size: 12px;
  font-weight: 600;
  margin-right: 6px;
  margin-bottom: 6px;
}

.course-badge.level-basico {
  background: #e8f5e9;
  color: #2e7d32;
}

.course-badge.level-intermedio {
  background: #fff3e0;
  color: #e65100;
}

.course-badge.level-avanzado {
  background: #ffebee;
  color: #c62828;
}

.course-badge.certification {
  background: #e3f2fd;
  color: #1565c0;
}

/* Modo Sin Distracciones */
html[data-distraction-free="true"] nav,
html[data-distraction-free="true"] footer,
html[data-distraction-free="true"] .floating-widgets {
  display: none !important;
}

html[data-distraction-free="true"] main {
  max-width: 800px;
  margin: 0 auto;
  padding: 40px 20px;
}

/* Generador de Preguntas IA */
.ai-quiz-generator {
  background: var(--color-bg-secondary);
  border: 2px solid var(--color-accent-primary);
  border-radius: 12px;
  padding: 20px;
  margin: 20px 0;
}

.ai-quiz-generator button {
  background: var(--color-accent-primary);
  color: white;
  border: none;
  padding: 10px 20px;
  border-radius: 8px;
  cursor: pointer;
  font-weight: 600;
  margin-right: 10px;
  transition: all 0.2s;
}

.ai-quiz-generator button:hover {
  background: var(--color-accent-secondary);
  transform: scale(1.05);
}

/* Resaltado de Conceptos Clave */
.key-concept {
  background: var(--color-highlight);
  border-left: 4px solid var(--color-highlight-border);
  padding: 12px 16px;
  margin: 16px 0;
  border-radius: 4px;
  font-weight: 500;
}

/* Resumen Automático */
.auto-summary {
  background: linear-gradient(135deg, var(--color-bg-secondary), var(--color-bg-tertiary));
  border-left: 4px solid var(--color-accent-primary);
  padding: 16px 20px;
  margin: 20px 0;
  border-radius: 8px;
  font-style: italic;
}

.auto-summary::before {
  content: '📋 Resumen:';
  display: block;
  font-weight: bold;
  font-style: normal;
  margin-bottom: 8px;
  color: var(--color-accent-primary);
}

/* Vista de Calendario de Estudio */
.study-calendar {
  background: var(--color-bg-primary);
  border: 1px solid var(--color-border);
  border-radius: 12px;
  padding: 24px;
  margin: 20px 0;
}

.calendar-week {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 8px;
  margin-top: 16px;
}

.calendar-day {
  background: var(--color-bg-secondary);
  border: 1px solid var(--color-border);
  border-radius: 8px;
  padding: 12px;
  min-height: 100px;
  font-size: 14px;
}

.calendar-day.has-study {
  background: var(--color-highlight);
  border-color: var(--color-highlight-border);
}

/* Sistema de Votos en Recursos */
.resource-votes {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-top: 12px;
}

.vote-btn {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 6px 12px;
  border: 1px solid var(--color-border);
  background: var(--color-bg-secondary);
  border-radius: 20px;
  cursor: pointer;
  transition: all 0.2s;
  font-size: 14px;
}

.vote-btn:hover {
  background: var(--color-bg-tertiary);
  border-color: var(--color-accent-primary);
}

.vote-btn.voted {
  background: var(--color-accent-primary);
  color: white;
  border-color: var(--color-accent-primary);
}

/* Consejos de Escritura IA en CV */
.cv-writing-tip {
  background: var(--color-bg-secondary);
  border-left: 3px solid var(--color-accent-tertiary);
  padding: 10px 14px;
  margin-top: 8px;
  border-radius: 4px;
  font-size: 13px;
  color: var(--color-text-secondary);
  animation: fadeIn 0.3s ease;
}

.cv-writing-tip::before {
  content: '💡 ';
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(-5px); }
  to { opacity: 1; transform: translateY(0); }
}

/* Sistema de XP y Niveles */
.xp-bar {
  background: var(--color-bg-tertiary);
  border-radius: 10px;
  height: 20px;
  overflow: hidden;
  margin: 10px 0;
}

.xp-fill {
  background: linear-gradient(90deg, var(--color-accent-primary), var(--color-accent-tertiary));
  height: 100%;
  transition: width 0.5s ease;
  display: flex;
  align-items: center;
  justify-content: flex-end;
  padding-right: 8px;
  color: white;
  font-size: 12px;
  font-weight: bold;
}

.level-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 8px 16px;
  background: linear-gradient(135deg, var(--color-accent-primary), var(--color-accent-secondary));
  color: white;
  border-radius: 20px;
  font-weight: bold;
  box-shadow: var(--shadow-md);
}

/* Mapa de Recursos Interactivo */
.resource-map {
  background: var(--color-bg-primary);
  border: 1px solid var(--color-border);
  border-radius: 12px;
  padding: 20px;
  margin: 20px 0;
}

.map-marker {
  width: 30px;
  height: 30px;
  background: var(--color-accent-primary);
  border: 3px solid white;
  border-radius: 50%;
  box-shadow: var(--shadow-md);
  cursor: pointer;
  transition: transform 0.2s;
}

.map-marker:hover {
  transform: scale(1.2);
}

/* Simulador de Prestaciones */
.benefits-calculator {
  background: var(--color-bg-secondary);
  border: 2px solid var(--color-border);
  border-radius: 12px;
  padding: 24px;
  margin: 20px 0;
}

.benefit-result {
  background: var(--color-highlight);
  border-left: 4px solid var(--color-accent-primary);
  padding: 16px;
  margin-top: 16px;
  border-radius: 8px;
  font-size: 18px;
  font-weight: bold;
}

/* Optimización de Carga - Lazy Loading */
.lazy-load {
  opacity: 0;
  transition: opacity 0.5s ease;
}

.lazy-load.loaded {
  opacity: 1;
}

/* Responsive para Móvil */
@media (max-width: 768px) {
  html[data-study-mode="true"] {
    font-size: 16px;
  }

  .pomodoro-widget {
    bottom: 70px;
    right: 10px;
    left: 10px;
    min-width: auto;
  }

  .calendar-week {
    grid-template-columns: 1fr;
  }
}

/* Modo Alto Contraste para Estudio */
html[data-study-mode="true"][data-high-contrast="true"] {
  --color-bg-primary: #000000;
  --color-bg-secondary: #1a1a1a;
  --color-text-primary: #ffffff;
  --color-text-secondary: #e0e0e0;
  --color-accent-primary: #00ff88;
  --color-accent-secondary: #ffaa00;
  --color-border: #333333;
  --color-highlight: #ffff00;
}

/* Animaciones Reducidas para Accesibilidad */
@media (prefers-reduced-motion: reduce) {
  .course-card,
  .pomodoro-btn,
  .vote-btn,
  .map-marker {
    transition: none;
  }

  .course-card:hover {
    transform: none;
  }
}


✅ Study Mode CSS created with 50+ styling rules

