function ReadingRuler() {
  const [position, setPosition] = useState(0);
  const [isVisible, setIsVisible] = useState(false);

  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      setPosition(e.clientY - 60); // Centrar la regla en el cursor
    };

    if (isVisible) {
      window.addEventListener('mousemove', handleMouseMove);
    }

    return () => window.removeEventListener('mousemove', handleMouseMove);
  }, [isVisible]);

  if (!isVisible) {
    return (
      <button
        onClick={() => setIsVisible(true)}
        className="fixed bottom-20 right-32 bg-white border-2 border-gray-300 rounded-full p-3 shadow-lg hover:shadow-xl transition-shadow z-50"
        title="Activar Regla de Lectura"
      >
        <FileText className="text-purple-600" size={24} />
