'use client';

import { useState, useEffect, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Volume2, VolumeX, MessageCircle, X, Sparkles, Heart } from 'lucide-react';
import { publicLottieAnimations } from '@/lib/multimedia';

interface CompanionMessage {
  id: string;
  text: string;
  timestamp: Date;
  type: 'greeting' | 'tip' | 'encouragement' | 'celebration';
}

export function PersistentCompanion() {
  const [isOpen, setIsOpen] = useState(false);
  const [isMuted, setIsMuted] = useState(false);
  const [currentMessage, setCurrentMessage] = useState<CompanionMessage | null>(null);
  const [animationState, setAnimationState] = useState<'idle' | 'speaking' | 'thinking' | 'happy'>('idle');
  const [messages, setMessages] = useState<CompanionMessage[]>([]);
  const speechSynthesisRef = useRef<SpeechSynthesis | null>(null);

  // Mensajes contextuales del acompañante
  const contextualMessages: Record<string, CompanionMessage[]> = {
    greeting: [
      { id: '1', text: '¡Hola! Soy Manos, tu acompañante. ¿En qué puedo ayudarte hoy?', timestamp: new Date(), type: 'greeting' },
      { id: '2', text: 'Bienvenido/a. Estoy aquí para guiarte en cada paso de tu nueva vida en España.', timestamp: new Date(), type: 'greeting' },
    ],
    tip: [
      { id: '3', text: '💡 Consejo: Usa el Modo Estudio para concentrarte mejor mientras lees.', timestamp: new Date(), type: 'tip' },
      { id: '4', text: '📝 Recuerda que puedes generar tu CV con IA en solo 5 minutos.', timestamp: new Date(), type: 'tip' },
      { id: '5', text: '🎧 Activa la lectura en voz alta si prefieres escuchar el contenido.', timestamp: new Date(), type: 'tip' },
    ],
    encouragement: [
      { id: '6', text: '💪 ¡Lo estás haciendo genial! Cada paso cuenta.', timestamp: new Date(), type: 'encouragement' },
      { id: '7', text: '🌟 Tu esfuerzo de hoy construye tu futuro mañana.', timestamp: new Date(), type: 'encouragement' },
      { id: '8', text: '🤝 No estás solo/a. Estoy aquí para ayudarte siempre.', timestamp: new Date(), type: 'encouragement' },
    ],
    celebration: [
      { id: '9', text: '🎉 ¡Felicidades! Has completado una lección. ¡Sigue así!', timestamp: new Date(), type: 'celebration' },
      { id: '10', text: '🏆 ¡Increíble! Has subido de nivel. Eres un/a crack.', timestamp: new Date(), type: 'celebration' },
    ],
  };

  // Inicializar Speech Synthesis
  useEffect(() => {
    if (typeof window !== 'undefined') {
      speechSynthesisRef.current = window.speechSynthesis;
    }
  }, []);

  // Mostrar mensaje contextual aleatorio cada cierto tiempo
  useEffect(() => {
    const interval = setInterval(() => {
      if (!isOpen && Math.random() > 0.7) {
        const types: Array<keyof typeof contextualMessages> = ['tip', 'encouragement', 'celebration'];
        const randomType = types[Math.floor(Math.random() * types.length)];
        const messages = contextualMessages[randomType];
        const randomMessage = messages[Math.floor(Math.random() * messages.length)];

        setCurrentMessage(randomMessage);
        setAnimationState('speaking');

        // Leer en voz alta si no está silenciado
        if (!isMuted && speechSynthesisRef.current) {
          const utterance = new SpeechSynthesisUtterance(randomMessage.text);
          utterance.lang = 'es-ES';
          utterance.rate = 0.9;
          utterance.pitch = 1.1;
          speechSynthesisRef.current.speak(utterance);
        }

        // Ocultar después de 8 segundos
        setTimeout(() => {
          setCurrentMessage(null);
          setAnimationState('idle');
        }, 8000);
      }
    }, 60000); // Cada minuto

    return () => clearInterval(interval);
  }, [isOpen, isMuted]);

  // Saludo inicial al cargar
  useEffect(() => {
    const timer = setTimeout(() => {
      const greeting = contextualMessages.greeting[0];
      setCurrentMessage(greeting);
      setAnimationState('speaking');

      if (!isMuted && speechSynthesisRef.current) {
        const utterance = new SpeechSynthesisUtterance(greeting.text);
        utterance.lang = 'es-ES';
        utterance.rate = 0.9;
        speechSynthesisRef.current.speak(utterance);
      }

      setTimeout(() => {
        setCurrentMessage(null);
        setAnimationState('idle');
      }, 8000);
    }, 3000);

    return () => clearTimeout(timer);
  }, []);

  const handleSpeak = (text: string) => {
    if (isMuted || !speechSynthesisRef.current) return;

    setAnimationState('speaking');
    const utterance = new SpeechSynthesisUtterance(text);
    utterance.lang = 'es-ES';
    utterance.rate = 0.9;
    utterance.pitch = 1.1;
    utterance.onend = () => setAnimationState('idle');
    speechSynthesisRef.current.speak(utterance);
  };

  const handleOpenChat = () => {
    setIsOpen(!isOpen);
    if (!isOpen) {
      setAnimationState('happy');
      handleSpeak('¡Hola! Estoy aquí para ayudarte.');
      setTimeout(() => setAnimationState('idle'), 3000);
    }
  };

  return (
    <>
      {/* Mensaje flotante */}
      <AnimatePresence>
        {currentMessage && !isOpen && (
          <motion.div
            initial={{ opacity: 0, y: 20, scale: 0.9 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: 20, scale: 0.9 }}
            className="fixed bottom-28 right-6 z-50 max-w-xs bg-white rounded-2xl shadow-2xl border-2 border-purple-200 p-4"
          >
            <div className="flex items-start gap-3">
              <div className="flex-shrink-0 w-10 h-10 bg-gradient-to-br from-purple-500 to-pink-500 rounded-full flex items-center justify-center text-white text-xl">
                🤗
              </div>
              <div className="flex-1">
                <p className="text-sm text-gray-800 leading-relaxed">{currentMessage.text}</p>
                <button
                  onClick={() => handleSpeak(currentMessage.text)}
                  className="mt-2 text-xs text-purple-600 hover:text-purple-800 flex items-center gap-1"
                >
                  <Volume2 size={12} />
                  Escuchar de nuevo
                </button>
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Avatar Flotante (Mascota) */}
      <motion.button
        onClick={handleOpenChat}
        animate={{
          scale: animationState === 'happy' ? [1, 1.2, 1] : 1,
          rotate: animationState === 'speaking' ? [0, -5, 5, 0] : 0,
        }}
        transition={{ duration: 0.5 }}
        className="fixed bottom-6 right-6 z-50 w-20 h-20 bg-gradient-to-br from-purple-500 via-pink-500 to-orange-500 rounded-full shadow-2xl flex items-center justify-center text-4xl hover:scale-110 transition-transform"
        whileHover={{ scale: 1.1 }}
        whileTap={{ scale: 0.95 }}
      >
        <motion.div
          animate={{
            y: animationState === 'idle' ? [0, -5, 0] : 0,
          }}
          transition={{
            duration: 2,
            repeat: animationState === 'idle' ? Infinity : 0,
            ease: 'easeInOut',
          }}
        >
          🤗
        </motion.div>

        {/* Indicador de voz activa */}
        {animationState === 'speaking' && (
          <motion.div
            initial={{ scale: 0 }}
            animate={{ scale: [1, 1.5, 1] }}
            transition={{ duration: 1, repeat: Infinity }}
            className="absolute -top-1 -right-1 w-6 h-6 bg-red-500 rounded-full flex items-center justify-center"
          >
            <Volume2 size={12} className="text-white" />
          </motion.div>
        )}
      </motion.button>

      {/* Botón de silenciar */}
      <motion.button
        onClick={() => setIsMuted(!isMuted)}
        className="fixed bottom-28 right-6 z-40 w-12 h-12 bg-white rounded-full shadow-lg flex items-center justify-center hover:scale-110 transition-transform border-2 border-gray-200"
        whileHover={{ scale: 1.1 }}
        whileTap={{ scale: 0.95 }}
      >
        {isMuted ? (
          <VolumeX size={20} className="text-gray-500" />
        ) : (
          <Volume2 size={20} className="text-purple-600" />
        )}
      </motion.button>

      {/* Chat del acompañante */}
      <AnimatePresence>
        {isOpen && (
          <motion.div
            initial={{ opacity: 0, y: 20, scale: 0.9 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: 20, scale: 0.9 }}
            className="fixed bottom-32 right-6 z-50 w-96 h-[500px] bg-white rounded-3xl shadow-2xl border-2 border-purple-200 overflow-hidden flex flex-col"
          >
            {/* Header */}
            <div className="bg-gradient-to-r from-purple-600 via-pink-600 to-orange-600 p-6 text-white">
              <div className="flex justify-between items-start">
                <div className="flex items-center gap-3">
                  <div className="w-14 h-14 bg-white/20 backdrop-blur-sm rounded-full flex items-center justify-center text-3xl">
                    🤗
                  </div>
                  <div>
                    <h3 className="text-xl font-bold">Manos</h3>
                    <p className="text-sm text-purple-100 flex items-center gap-1">
                      <Heart size={12} fill="currentColor" />
                      Tu acompañante
                    </p>
                  </div>
                </div>
                <button
                  onClick={() => setIsOpen(false)}
                  className="text-white/80 hover:text-white hover:bg-white/20 rounded-full p-1"
                >
                  <X size={20} />
                </button>
              </div>
            </div>

            {/* Mensajes */}
            <div className="flex-1 overflow-y-auto p-4 space-y-3 bg-gradient-to-b from-purple-50 to-pink-50">
              {/* Saludo inicial */}
              <motion.div
                initial={{ opacity: 0, x: -20 }}
