                  </p>
                  <p className="text-sm text-gray-600 mt-2">
                    Estoy aquí para guiarte en cada paso. Puedo:
                  </p>
                  <ul className="text-xs text-gray-600 mt-2 space-y-1">
                    <li>📚 Ayudarte a entender el contenido</li>
                    <li>🔊 Leer en voz alta cualquier texto</li>
                    <li>💡 Darte consejos personalizados</li>
                    <li>🎉 Celebrar tus logros contigo</li>
                  </ul>
                </div>
              </motion.div>

              {/* Mensajes contextuales */}
              {contextualMessages.tip.map((msg, i) => (
                <motion.div
                  key={msg.id}
                  initial={{ opacity: 0, x: 20 }}
                  animate={{ opacity: 1, x: 0 }}
                  transition={{ delay: i * 0.2 }}
