}

export function ContextualGallery({ section, variant = 'hero' }: ContextualGalleryProps) {
  const [currentIndex, setCurrentIndex] = useState(0);
  const [mediaType, setMediaType] = useState<'image' | 'video'>('image');
  const [isMuted, setIsMuted] = useState(true);

  // Mapeo de secciones a categorías de multimedia
  const sectionMediaMap: Record<string, { images: string[], videos: string[] }> = {
    home: {
      images: publicImages.diversity,
      videos: publicVideos.home,
    },
    learn: {
      images: publicImages.education,
      videos: publicVideos.education,
    },
    cv: {
      images: publicImages.work,
      videos: publicVideos.work,
    },
    office: {
      images: publicImages.technology,
      videos: publicVideos.technology,
    },
    resources: {
      images: publicImages.documents,
      videos: publicVideos.work,
    },
    rights: {
      images: publicImages.documents,
      videos: publicVideos.spain,
    },
    tools: {
      images: publicImages.technology,
      videos: publicVideos.technology,
    },
    events: {
      images: publicImages.spain,
      videos: publicVideos.spain,
    },
    courses: {
      images: publicImages.education,
      videos: publicVideos.education,
    },
  };

  const media = sectionMediaMap[section] || sectionMediaMap.home;
  const currentMedia = mediaType === 'image' ? media.images : media.videos;

  // Auto-rotar cada 8 segundos
  useEffect(() => {
    const interval = setInterval(() => {
      setCurrentIndex((prev) => (prev + 1) % currentMedia.length);
    }, 8000);

    return () => clearInterval(interval);
  }, [currentMedia.length]);

  const nextMedia = () => {
    setCurrentIndex((prev) => (prev + 1) % currentMedia.length);
  };

  const prevMedia = () => {
    setCurrentIndex((prev) => (prev - 1 + currentMedia.length) % currentMedia.length);
  };

  if (variant === 'background') {
    return (
      <div className="absolute inset-0 overflow-hidden">
        <AnimatePresence mode="wait">
          {mediaType === 'image' ? (
            <motion.div
              key={`img-${currentIndex}`}
              initial={{ opacity: 0 }}
              animate={{ opacity: 0.3 }}
              exit={{ opacity: 0 }}
              transition={{ duration: 1 }}
              className="absolute inset-0"
            >
              <img
                src={currentMedia[currentIndex]}
                alt=""
                className="w-full h-full object-cover"
              />
            </motion.div>
          ) : (
            <motion.video
              key={`video-${currentIndex}`}
              initial={{ opacity: 0 }}
              animate={{ opacity: 0.3 }}
              exit={{ opacity: 0 }}
              transition={{ duration: 1 }}
              autoPlay
              loop
              muted={isMuted}
              className="absolute inset-0 w-full h-full object-cover"
            >
              <source src={currentMedia[currentIndex]} type="video/mp4" />
            </motion.video>
          )}
        </AnimatePresence>

        {/* Overlay */}
        <div className="absolute inset-0 bg-gradient-to-br from-white/80 via-white/60 to-transparent" />
      </div>
    );
  }

  if (variant === 'card') {
    return (
      <div className="relative w-full h-64 rounded-2xl overflow-hidden shadow-lg">
        <AnimatePresence mode="wait">
          {mediaType === 'image' ? (
            <motion.img
              key={`img-${currentIndex}`}
              src={currentMedia[currentIndex]}
              alt=""
              initial={{ opacity: 0, scale: 1.1 }}
              animate={{ opacity: 1, scale: 1 }}
              exit={{ opacity: 0, scale: 0.9 }}
              transition={{ duration: 0.5 }}
              className="w-full h-full object-cover"
            />
          ) : (
            <motion.video
              key={`video-${currentIndex}`}
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              autoPlay
              loop
              muted
              className="w-full h-full object-cover"
            >
              <source src={currentMedia[currentIndex]} type="video/mp4" />
            </motion.video>
          )}
        </AnimatePresence>

        {/* Controls */}
        <div className="absolute bottom-4 left-4 right-4 flex items-center justify-between">
          <button
            onClick={prevMedia}
            className="p-2 bg-white/90 backdrop-blur-sm rounded-full shadow-lg hover:bg-white transition-colors"
          >
            <ChevronLeft size={20} />
          </button>

          <div className="flex items-center gap-2">
            <button
              onClick={() => setMediaType('image')}
              className={`p-2 rounded-full transition-colors ${
                mediaType === 'image' ? 'bg-purple-600 text-white' : 'bg-white/90 text-gray-700'
              }`}
            >
              <ImageIcon size={16} />
            </button>
            <button
              onClick={() => setMediaType('video')}
              className={`p-2 rounded-full transition-colors ${
                mediaType === 'video' ? 'bg-purple-600 text-white' : 'bg-white/90 text-gray-700'
              }`}
            >
              <Video size={16} />
            </button>
          </div>

          <button
            onClick={nextMedia}
            className="p-2 bg-white/90 backdrop-blur-sm rounded-full shadow-lg hover:bg-white transition-colors"
          >
            <ChevronRight size={20} />
          </button>
        </div>

        {/* Dots */}
        <div className="absolute bottom-16 left-1/2 -translate-x-1/2 flex gap-2">
          {currentMedia.map((_, i) => (
            <button
              key={i}
              onClick={() => setCurrentIndex(i)}
              className={`w-2 h-2 rounded-full transition-all ${
                i === currentIndex ? 'bg-white w-8' : 'bg-white/50'
              }`}
            />
          ))}
        </div>
      </div>
    );
  }

  // Variante Hero (default)
  return (
    <div className="relative w-full h-[500px] rounded-3xl overflow-hidden shadow-2xl">
      <AnimatePresence mode="wait">
        {mediaType === 'image' ? (
          <motion.img
            key={`img-${currentIndex}`}
            src={currentMedia[currentIndex]}
            alt=""
            initial={{ opacity: 0, scale: 1.1 }}
            animate={{ opacity: 1, scale: 1 }}
