            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            autoPlay
            loop
            muted={isMuted}
            className="w-full h-full object-cover"
          >
            <source src={currentMedia[currentIndex]} type="video/mp4" />
          </motion.video>
        )}
      </AnimatePresence>

      {/* Overlay */}
      <div className="absolute inset-0 bg-gradient-to-t from-black/60 via-transparent to-transparent" />

      {/* Content */}
      <div className="absolute inset-0 flex items-end p-8">
        <div className="text-white">
          <h2 className="text-4xl font-bold mb-2 drop-shadow-lg">
            {section === 'home' && 'Bienvenido/a a Manos Abiertas'}
            {section === 'learn' && 'Aprende Inteligencia Artificial'}
            {section === 'cv' && 'Crea tu CV Profesional'}
            {section === 'office' && 'Domina el Pack Office'}
            {section === 'resources' && 'Recursos Verificados'}
            {section === 'rights' && 'Conoce tus Derechos'}
            {section === 'tools' && 'Herramientas Prácticas'}
