document.addEventListener('mousemove',function(e){if(document.documentElement.getAttribute('data-reading')==='ruler'){$('ruler').style.top=(e.clientY-55)+'px'}});
/* Pomodoro */
var pom={left:1500,run:false,mode:'work',iv:null};
