```typescript
// src/hooks/use-book-search.ts
"use client";

import { useState, useEffect, useRef, useCallback } from "react";

export interface BookSearchHit {
  id: string;
  title: string;
  authors: string[];
  description?: string;
  coverUrl?: string;
  language: string;
  source: string;
  rating: number;
  _formatted?: Record<string, string>;
}

export interface BookSearchFilters {
  language?: string;
  source?: string;
  copyright?: string;
  subjects?: string[];
  hasAudio?: boolean;
}

export interface UseBookSearchResult {
  query: string;
  setQuery: (q: string) => void;
  results: BookSearchHit[];
  loading: boolean;
  error: string | null;
  total: number;
  facets: Record<string, Record<string, number>>;
  filters: BookSearchFilters;
  setFilters: (f: BookSearchFilters) => void;
  reset: () => void;
  hasMore: boolean;
  loadMore: () => void;
}

export function useBookSearch(options: {
  debounceMs?: number;
  limit?: number;
  initialQuery?: string;
} = {}): UseBookSearchResult {
  const { debounceMs = 400, limit = 20, initialQuery = "" } = options;

  const [query, setQuery] = useState(initialQuery);
  const [results, setResults] = useState<BookSearchHit[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [total, setTotal] = useState(0);
  const [page, setPage] = useState(1);
  const [facets, setFacets] = useState<Record<string, Record<string, number>>>({});
  const [filters, setFiltersState] = useState<BookSearchFilters>({});

  const abortRef = useRef<AbortController | null>(null);

  const search = useCallback(async (
    q: string,
    f: BookSearchFilters,
    p: number,
    append: boolean
  ) => {
    if (!q || q.length < 2) {
      setResults([]);
      setTotal(0);
      setFacets({});
      return;
    }

    if (abortRef.current) abortRef.current.abort();
    abortRef.current = new AbortController();

    setLoading(true);
    setError(null);

    try {
      const params = new URLSearchParams({
        q,
        page: String(p),
        limit: String(limit),
      });

      if (f.language) params.set("language", f.language);
      if (f.source) params.set("source", f.source);
      if (f.copyright) params.set("copyright", f.copyright);
      if (f.subjects?.length) {
        f.subjects.forEach(s => params.append("subjects", s));
      }
      if (f.hasAudio !== undefined) params.set("hasAudio", String(f.hasAudio));

      const res = await fetch(`/api/books/search?${params}`, {
        signal: abortRef.current.signal,
      });

      if (!res.ok) throw new Error(`Search failed: ${res.status}`);

      const data = await res.json();

      if (append) {
        setResults(prev => [...prev, ...data.hits]);
      } else {
        setResults(data.hits);
      }
      setTotal(data.estimatedTotalHits);
      if (data.facetDistribution) setFacets(data.facetDistribution);
    } catch (err: any) {
      if (err.name !== "AbortError") {
        setError(err.message);
      }
    } finally {
      setLoading(false);
    }
  }, [limit]);

  // Debounced search
  useEffect(() => {
    if (query.length < 2) {
      setResults([]);
      setTotal(0);
      return;
    }

    const timer = setTimeout(() => {
      setPage(1);
      search(query, filters, 1, false);
    }, debounceMs);

    return () => clearTimeout(timer);
  }, [query, filters, debounceMs, search]);

  const setFilters = useCallback((f: BookSearchFilters) => {
    setFiltersState(f);
    setPage(1);
  }, []);

  const reset = useCallback(() => {
    setQuery("");
    setFiltersState({});
    setResults([]);
    setTotal(0);
    setPage(1);
  }, []);

  const loadMore = useCallback(() => {
    const nextPage = page + 1;
    setPage(nextPage);
    search(query, filters, nextPage, true);
  }, [page, query, filters, search]);

  const hasMore = results.length < total;

  return {
    query,
    setQuery,
    results,
    loading,
    error,
    total,
    facets,
    filters,
    setFilters,
    reset,
    hasMore,
    loadMore,
  };
}
