'use client';

import { useState, useMemo, useEffect } from 'react';
import { BookOpen, Clock, Award, Filter, Search, ExternalLink, CheckCircle2, Star, TrendingUp, Calendar, Play, Pause, RotateCcw, Lightbulb, FileText, Target } from 'lucide-react';
import { externalCourses, courseCategories, getCourseById, getPrerequisites, getNextSteps } from '@/lib/external-courses';

// Tipos
type Level = 'basico' | 'intermedio' | 'avanzado';
type Category = string;

// Hook para el Temporizador Pomodoro
function usePomodoro() {
  const [timeLeft, setTimeLeft] = useState(25 * 60); // 25 minutos
  const [isRunning, setIsRunning] = useState(false);
  const [mode, setMode] = useState<'work' | 'break'>('work');

  useEffect(() => {
    if (!isRunning) return;

    const interval = setInterval(() => {
      setTimeLeft(prev => {
        if (prev <= 1) {
          // Cambiar de modo
          if (mode === 'work') {
            setMode('break');
            return 5 * 60; // 5 minutos de descanso
          } else {
            setMode('work');
            return 25 * 60; // 25 minutos de trabajo
          }
        }
        return prev - 1;
      });
    }, 1000);

    return () => clearInterval(interval);
  }, [isRunning, mode]);

  const toggle = () => setIsRunning(!isRunning);
  const reset = () => {
    setTimeLeft(25 * 60);
    setIsRunning(false);
    setMode('work');
  };

  const minutes = Math.floor(timeLeft / 60);
  const seconds = timeLeft % 60;

  return {
    timeLeft,
    isRunning,
    mode,
    toggle,
    reset,
    display: `${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`
  };
}

// Hook para Progreso de Cursos Externos
function useCourseProgress() {
  const [progress, setProgress] = useState<Record<string, 'not_started' | 'in_progress' | 'completed'>>(() => {
    if (typeof window === 'undefined') return {};
    const saved = localStorage.getItem('externalCoursesProgress');
    return saved ? JSON.parse(saved) : {};
  });

  useEffect(() => {
    localStorage.setItem('externalCoursesProgress', JSON.stringify(progress));
  }, [progress]);

  const updateProgress = (courseId: string, status: 'not_started' | 'in_progress' | 'completed') => {
    setProgress(prev => ({ ...prev, [courseId]: status }));
  };

  const getProgress = (courseId: string) => progress[courseId] || 'not_started';

  const stats = useMemo(() => {
    const total = externalCourses.length;
    const completed = Object.values(progress).filter(s => s === 'completed').length;
    const inProgress = Object.values(progress).filter(s => s === 'in_progress').length;
    return { total, completed, inProgress, percentage: Math.round((completed / total) * 100) };
  }, [progress]);

  return { progress, updateProgress, getProgress, stats };
}

// Componente de Tarjeta de Curso
function CourseCard({ course, progress, onProgressChange }: { 
  course: any; 
  progress: 'not_started' | 'in_progress' | 'completed';
  onProgressChange: (status: 'not_started' | 'in_progress' | 'completed') => void;
}) {
  const prerequisites = getPrerequisites(course.id);
  const nextSteps = getNextSteps(course.id);

  const levelColors = {
    basico: 'bg-green-100 text-green-800',
    intermedio: 'bg-orange-100 text-orange-800',
    avanzado: 'bg-red-100 text-red-800'
  };

  const statusColors = {
    not_started: 'bg-gray-100 text-gray-600',
    in_progress: 'bg-blue-100 text-blue-800',
    completed: 'bg-green-100 text-green-800'
  };

  const statusLabels = {
    not_started: 'Sin empezar',
    in_progress: 'En progreso',
    completed: 'Completado'
  };

  return (
    <div className="course-card">
      {/* Badge de Categoría */}
      <div className="flex items-start justify-between mb-3">
        <div className="flex flex-wrap gap-2">
          <span className={`course-badge ${levelColors[course.level]}`}>
            {course.level.charAt(0).toUpperCase() + course.level.slice(1)}
          </span>
          {course.certification && (
            <span className="course-badge certification">
              <Award size={12} /> Certificado
            </span>
          )}
        </div>
        <span className={`course-badge ${statusColors[progress]}`}>
          {progress === 'completed' && <CheckCircle2 size={12} />}
          {statusLabels[progress]}
        </span>
      </div>

      {/* Título y Proveedor */}
      <h3 className="text-xl font-bold mb-2 text-gray-900">{course.title}</h3>
      <p className="text-sm text-gray-600 mb-3">
        <span className="font-semibold">{course.provider}</span> • {course.duration}
      </p>

      {/* Descripción */}
      <p className="text-gray-700 mb-4 line-clamp-3">{course.description}</p>

      {/* Tags */}
      <div className="flex flex-wrap gap-2 mb-4">
        {course.tags.slice(0, 4).map((tag: string, i: number) => (
          <span key={i} className="text-xs bg-gray-100 text-gray-600 px-2 py-1 rounded">
            {tag}
          </span>
        ))}
      </div>

      {/* Prerequisitos */}
      {prerequisites.length > 0 && (
        <div className="mb-3 p-3 bg-yellow-50 border border-yellow-200 rounded-lg">
          <p className="text-xs font-semibold text-yellow-800 mb-1">📚 Prerequisitos:</p>
          <ul className="text-xs text-yellow-700">
            {prerequisites.map((prereq: any) => (
              <li key={prereq.id}>• {prereq.title}</li>
            ))}
          </ul>
        </div>
      )}

      {/* Siguientes Pasos */}
      {nextSteps.length > 0 && (
        <div className="mb-4 p-3 bg-blue-50 border border-blue-200 rounded-lg">
          <p className="text-xs font-semibold text-blue-800 mb-1">➡️ Siguientes pasos:</p>
          <ul className="text-xs text-blue-700">
            {nextSteps.map((next: any) => (
              <li key={next.id}>• {next.title}</li>
            ))}
          </ul>
        </div>
      )}

      {/* Acciones */}
      <div className="flex gap-2 flex-wrap">
        <a
          href={course.url}
          target="_blank"
          rel="noopener noreferrer"
          className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors text-sm font-medium"
        >
          <ExternalLink size={16} />
          Acceder al curso
        </a>

        <select
          value={progress}
          onChange={(e) => onProgressChange(e.target.value as any)}
          className="px-3 py-2 border border-gray-300 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
        >
