// Hook para el Temporizador Pomodoro
function usePomodoro() {
  const [timeLeft, setTimeLeft] = useState(25 * 60); // 25 minutos
  const [isRunning, setIsRunning] = useState(false);
  const [mode, setMode] = useState<'work' | 'break'>('work');

  useEffect(() => {
    if (!isRunning) return;

    const interval = setInterval(() => {
      setTimeLeft(prev => {
        if (prev <= 1) {
          // Cambiar de modo
          if (mode === 'work') {
            setMode('break');
            return 5 * 60; // 5 minutos de descanso
          } else {
            setMode('work');
            return 25 * 60; // 25 minutos de trabajo
          }
        }
        return prev - 1;
      });
    }, 1000);

    return () => clearInterval(interval);
  }, [isRunning, mode]);

  const toggle = () => setIsRunning(!isRunning);
  const reset = () => {
    setTimeLeft(25 * 60);
    setIsRunning(false);
    setMode('work');
  };

  const minutes = Math.floor(timeLeft / 60);
  const seconds = timeLeft % 60;

  return {
    timeLeft,
    isRunning,
    mode,
    toggle,
    reset,
    display: `${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`
  };
}

// Hook para Progreso de Cursos Externos
function useCourseProgress() {
  const [progress, setProgress] = useState<Record<string, 'not_started' | 'in_progress' | 'completed'>>(() => {
    if (typeof window === 'undefined') return {};
    const saved = localStorage.getItem('externalCoursesProgress');
    return saved ? JSON.parse(saved) : {};
  });

  useEffect(() => {
    localStorage.setItem('externalCoursesProgress', JSON.stringify(progress));
  }, [progress]);

  const updateProgress = (courseId: string, status: 'not_started' | 'in_progress' | 'completed') => {
    setProgress(prev => ({ ...prev, [courseId]: status }));
  };

  const getProgress = (courseId: string) => progress[courseId] || 'not_started';

  const stats = useMemo(() => {
    const total = externalCourses.length;
    const completed = Object.values(progress).filter(s => s === 'completed').length;
    const inProgress = Object.values(progress).filter(s => s === 'in_progress').length;
    return { total, completed, inProgress, percentage: Math.round((completed / total) * 100) };
  }, [progress]);

  return { progress, updateProgress, getProgress, stats };
}

