import { persist } from 'zustand/middleware';

interface StudyState {
  studyMode: boolean;
  distractionFree: boolean;
  highContrast: boolean;
  readingRuler: boolean;
  pomodoroEnabled: boolean;

  // Acciones
  toggleStudyMode: () => void;
  toggleDistractionFree: () => void;
  toggleHighContrast: () => void;
  toggleReadingRuler: () => void;
  togglePomodoro: () => void;

  // Aplicar al HTML
  applyToDocument: () => void;
}

export const useStudyStore = create<StudyState>()(
  persist(
    (set, get) => ({
      studyMode: false,
      distractionFree: false,
      highContrast: false,
      readingRuler: false,
      pomodoroEnabled: false,

      toggleStudyMode: () => {
        set((state) => {
          const newValue = !state.studyMode;
          if (typeof document !== 'undefined') {
            document.documentElement.setAttribute('data-study-mode', String(newValue));
          }
          return { studyMode: newValue };
        });
      },

      toggleDistractionFree: () => {
        set((state) => {
          const newValue = !state.distractionFree;
          if (typeof document !== 'undefined') {
            document.documentElement.setAttribute('data-distraction-free', String(newValue));
          }
          return { distractionFree: newValue };
        });
      },

      toggleHighContrast: () => {
        set((state) => {
          const newValue = !state.highContrast;
          if (typeof document !== 'undefined') {
            document.documentElement.setAttribute('data-high-contrast', String(newValue));
          }
          return { highContrast: newValue };
        });
      },

      toggleReadingRuler: () => {
        set((state) => ({ readingRuler: !state.readingRuler }));
      },

      togglePomodoro: () => {
        set((state) => ({ pomodoroEnabled: !state.pomodoroEnabled }));
      },

      applyToDocument: () => {
        const state = get();
        if (typeof document !== 'undefined') {
          document.documentElement.setAttribute('data-study-mode', String(state.studyMode));
          document.documentElement.setAttribute('data-distraction-free', String(state.distractionFree));
          document.documentElement.setAttribute('data-high-contrast', String(state.highContrast));
        }
      }
    }),
    {
      name: 'study-mode-storage',
      onRehydrateStorage: () => {
        return (state) => {
          if (state) {
            state.applyToDocument();
          }
        };
      }
    }
  )
);

// Hook para XP y Niveles
interface XPState {
  xp: number;
  level: string;
  achievements: string[];

  addXP: (amount: number) => void;
  addAchievement: (achievement: string) => void;
  getLevelInfo: () => { level: number; title: string; xpToNext: number };
}

const LEVELS = [
  { minXP: 0, title: 'Recién Llegado', emoji: '👋' },
  { minXP: 100, title: 'Explorador', emoji: '🗺️' },
  { minXP: 300, title: 'Aprendiz', emoji: '📚' },
  { minXP: 600, title: 'Integrado', emoji: '🤝' },
  { minXP: 1000, title: 'Experto', emoji: '⭐' },
  { minXP: 2000, title: 'Maestro', emoji: '🎓' },
  { minXP: 5000, title: 'Mentor', emoji: '👑' }
];

export const useXPStore = create<XPState>()(
  persist(
    (set, get) => ({
      xp: 0,
      level: 'Recién Llegado',
      achievements: [],

      addXP: (amount) => {
        set((state) => {
          const newXP = state.xp + amount;
          const currentLevel = LEVELS.filter(l => newXP >= l.minXP).pop();
          return {
            xp: newXP,
            level: currentLevel?.title || state.level
          };
        });
      },

      addAchievement: (achievement) => {
        set((state) => {
          if (state.achievements.includes(achievement)) return state;
          return {
            achievements: [...state.achievements, achievement]
          };
        });
      },

      getLevelInfo: () => {
        const state = get();
        const currentIndex = LEVELS.findIndex(l => l.title === state.level);
        const current = LEVELS[currentIndex];
        const next = LEVELS[currentIndex + 1];

        return {
          level: currentIndex + 1,
          title: current.title,
          xpToNext: next ? next.minXP - state.xp : 0
        };
      }
    }),
    {
      name: 'xp-storage'
    }
  )
);


