            const arrayBuffer = await response.arrayBuffer();
            const audioBuffer = await audioContextRef.current.decodeAudioData(arrayBuffer);
            buffersRef.current[name] = audioBuffer;
          } catch (e) {
            console.warn(`Could not load sound: ${name}`, e);
          }
        }

        isInitializedRef.current = true;
      } catch (e) {
        console.warn('Audio context not supported', e);
      }
    };

    // Inicializar solo después de interacción del usuario (política de autoplay)
    const handleUserInteraction = () => {
      initAudio();
      window.removeEventListener('click', handleUserInteraction);
      window.removeEventListener('keydown', handleUserInteraction);
    };

    window.addEventListener('click', handleUserInteraction);
    window.addEventListener('keydown', handleUserInteraction);

    return () => {
      window.removeEventListener('click', handleUserInteraction);
      window.removeEventListener('keydown', handleUserInteraction);
    };
  }, [enabled]);

  const playSound = useCallback((soundName: keyof typeof publicAudio.uiSounds, volume: number = 0.3) => {
    if (!enabled || !audioContextRef.current || !buffersRef.current[soundName]) return;

    const buffer = buffersRef.current[soundName];
    const source = audioContextRef.current.createBufferSource();
    const gainNode = audioContextRef.current.createGain();

    source.buffer = buffer;
    gainNode.gain.value = volume;

    source.connect(gainNode);
    gainNode.connect(audioContextRef.current.destination);

    source.start(0);
  }, [enabled]);

  return {
    playClick: () => playSound('click', 0.2),
    playSuccess: () => playSound('success', 0.3),
    playNotification: () => playSound('notification', 0.25),
    playError: () => playSound('error', 0.3),
    playWhoosh: () => playSound('whoosh', 0.2),
  };
}

// Hook para música de fondo ambiental
export function useBackgroundMusic() {
  const audioRef = useRef<HTMLAudioElement | null>(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [currentTrack, setCurrentTrack] = useState(0);

  const tracks = publicAudio.ambient;

  useEffect(() => {
    audioRef.current = new Audio(tracks[currentTrack]);
    audioRef.current.loop = true;
    audioRef.current.volume = 0.2;

    const handleEnded = () => {
      setCurrentTrack((prev) => (prev + 1) % tracks.length);
    };

    audioRef.current.addEventListener('ended', handleEnded);

    return () => {
      if (audioRef.current) {
        audioRef.current.removeEventListener('ended', handleEnded);
        audioRef.current.pause();
      }
    };
  }, [currentTrack, tracks]);

  const togglePlay = () => {
    if (!audioRef.current) return;

    if (isPlaying) {
      audioRef.current.pause();
    } else {
      audioRef.current.play().catch(console.warn);
    }
    setIsPlaying(!isPlaying);
  };

  const setVolume = (volume: number) => {
    if (audioRef.current) {
      audioRef.current.volume = Math.max(0, Math.min(1, volume));
    }
  };

  const nextTrack = () => {
    setCurrentTrack((prev) => (prev + 1) % tracks.length);
  };

  const prevTrack = () => {
    setCurrentTrack((prev) => (prev - 1 + tracks.length) % tracks.length);
  };

  return {
    isPlaying,
    togglePlay,
    setVolume,
    nextTrack,
    prevTrack,
    currentTrack: tracks[currentTrack],
    trackName: ['Ambiental', 'Piano Suave', 'Meditación'][currentTrack],
  };
}
"""

