## 1. SCHEMA PRISMA COMPLETO (ampliado)

```prisma
// prisma/schema.prisma
generator client {
  provider        = "prisma-client-js"
  previewFeatures = ["fullTextSearch", "postgresqlExtensions"]
}

datasource db {
  provider   = "postgresql"
  url        = env("DATABASE_URL")
  directUrl  = env("DIRECT_URL")
  extensions = [pgTrgm]
}

// ═══════════════════════════════════════════════════════════════
// MODELOS CORE DEL BANCO DE LIBROS
// ═══════════════════════════════════════════════════════════════

model Book {
  id              String       @id @default(cuid())
  externalId      String       @unique
  source          BookSource

  title           String
  subtitle        String?
  authors         String[]     @default([])
  translators     String[]     @default([])
  publisher       String?
  publishDate     DateTime?
  language        String       @default("es")
  originalLang    String?

  description     String?      @db.Text
  summary         String?      @db.Text
  subjects        String[]     @default([])
  keywords        String[]     @default([])
  series          String?
  volume          Int?

  // Archivos
  epubPath        String?
  pdfPath         String?
  htmlPath        String?
  txtPath         String?
  coverPath       String?
  thumbnailPath   String?
  audioPath       String?      // audiolibro

  // URLs externas (fallback)
  epubUrl         String?
  pdfUrl          String?
  htmlUrl         String?
  coverUrl        String?
  sourceUrl       String?      // URL original

  // Metadatos físicos
  fileSize        Int?
  pageCount       Int?
  wordCount       Int?
  duration        Int?         // segundos (audiolibro)
  lexile          Int?         // nivel de lectura
  gradeLevel      String?

  // Licencia
  license         String       @default("unknown")
  copyrightStatus CopyrightStatus @default(UNKNOWN)
  commercialUse   Boolean      @default(false)
  derivativeUse   Boolean      @default(false)
  attributionReq  Boolean      @default(false)

  // Sistema
  ingestStatus    IngestStatus @default(PENDING)
  ingestError     String?
  lastVerified    DateTime     @default(now())
  verifiedBy      String?
  checksumSha256  String?

  // Métricas
  viewCount       Int          @default(0)
  downloadCount   Int          @default(0)
  readCount       Int          @default(0)
  favoriteCount   Int          @default(0)
  rating          Float        @default(0)
  ratingCount     Int          @default(0)

  // Fechas
  createdAt       DateTime     @default(now())
  updatedAt       DateTime     @updatedAt

  // Relaciones
  chapters        Chapter[]
  annotations     Annotation[]
  ttsCache        TTSCache[]
  readingProgress ReadingProgress[]
  favorites       Favorite[]
  collections     BookCollectionItem[]
  reviews         Review[]

  @@index([language, subjects])
  @@index([source, ingestStatus])
  @@index([copyrightStatus])
  @@index([createdAt])
  @@index([viewCount(sort: Desc)])
  @@fulltext([title, description, summary])
}

model Chapter {
  id          String   @id @default(cuid())
  bookId      String
  book        Book     @relation(fields: [bookId], references: [id], onDelete: Cascade)

  number      Int
  title       String
  content     String   @db.Text
  htmlContent String?  @db.Text
  wordCount   Int      @default(0)
  duration    Int?     // estimado en segundos
  audioPath   String?
  audioUrl    String?

  createdAt   DateTime @default(now())

  @@unique([bookId, number])
  @@index([bookId])
}

model TTSCache {
  id         String   @id @default(cuid())
  bookId     String
  book       Book     @relation(fields: [bookId], references: [id], onDelete: Cascade)
  chapterId  String?

  engine     TTSEngine
  voice      String
  language   String
  rate       Float    @default(1.0)
  pitch      Float    @default(1.0)

  audioPath  String
  audioUrl   String?
  duration   Int      @default(0)
  fileSize   Int      @default(0)

  hits       Int      @default(0)
  lastHit    DateTime @default(now())

  createdAt  DateTime @default(now())

  @@unique([bookId, chapterId, engine, voice, language, rate, pitch])
  @@index([bookId, engine])
}

model Annotation {
  id        String   @id @default(cuid())
  bookId    String
  book      Book     @relation(fields: [bookId], references: [id], onDelete: Cascade)

  userId    String?
  chapterId String?
  position  Json     // { chapter, offset, start, end }
  content   String   @db.Text
  type      AnnotationType @default(HIGHLIGHT)
