### 6.3 Hook TTS Player

```typescript
// src/hooks/use-tts-player.ts
"use client";

import { useState, useEffect, useRef, useCallback } from "react";

export interface TTSPlayerOptions {
  src?: string;
  text?: string;
  voice?: string;
  rate?: number;
  pitch?: number;
  onEnd?: () => void;
  onBoundary?: (e: { charIndex: number; charLength: number }) => void;
}

export function useTTSPlayer(options: TTSPlayerOptions = {}) {
  const {
    src,
    text,
    voice = "es-ES-ElviraNeural",
    rate = 1.0,
    pitch = 1.0,
    onEnd,
    onBoundary,
  } = options;

  const [playing, setPlaying] = useState(false);
  const [paused, setPaused] = useState(false);
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(0);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [charIndex, setCharIndex] = useState(0);

  const audioRef = useRef<HTMLAudioElement | null>(null);
  const utteranceRef = useRef<SpeechSynthesisUtterance | null>(null);

  // Modo audio (archivo)
  useEffect(() => {
    if (!src) return;

    setLoading(true);
    const audio = new Audio(src);
    audio.preload = "metadata";

    audio.addEventListener("loadedmetadata", () => {
      setDuration(audio.duration);
      setLoading(false);
    });
    audio.addEventListener("timeupdate", () => {
      setCurrentTime(audio.currentTime);
    });
    audio.addEventListener("ended", () => {
      setPlaying(false);
      setCurrentTime(0);
      onEnd?.();
    });
    audio.addEventListener("error", () => {
      setError("Error cargando audio");
      setLoading(false);
    });

    audioRef.current = audio;

    return () => {
      audio.pause();
      audio.src = "";
    };
  }, [src, onEnd]);

  // Modo Web Speech (síntesis)
  const speakText = useCallback(async () => {
    if (!text || !window.speechSynthesis) return;

    window.speechSynthesis.cancel();

    const utterance = new SpeechSynthesisUtterance(text);
    utterance.lang = voice.slice(0, 5);
    utterance.rate = rate;
    utterance.pitch = pitch;

    // Seleccionar voz
    const voices = window.speechSynthesis.getVoices();
    const match = voices.find(v => v.name.includes(voice)) ||
                  voices.find(v => v.lang === voice.slice(0, 5)) ||
                  voices.find(v => v.lang.startsWith("es"));
    if (match) utterance.voice = match;

    utterance.addEventListener("start", () => {
      setPlaying(true);
      setPaused(false);
    });
    utterance.addEventListener("end", () => {
      setPlaying(false);
      setCharIndex(0);
      onEnd?.();
    });
    utterance.addEventListener("boundary", (e: SpeechSynthesisEvent) => {
      setCharIndex(e.charIndex);
      onBoundary?.({ charIndex: e.charIndex, charLength: e.charLength ?? 0 });
    });
    utterance.addEventListener("error", () => {
      setError("Error en síntesis de voz");
      setPlaying(false);
    });

    utteranceRef.current = utterance;
    window.speechSynthesis.speak(utterance);
  }, [text, voice, rate, pitch, onEnd, onBoundary]);

  const play = useCallback(async () => {
    setError(null);

    if (src && audioRef.current) {
      try {
        await audioRef.current.play();
        setPlaying(true);
        setPaused(false);
      } catch (err) {
        setError("Error al reproducir");
      }
    } else if (text) {
      if (paused && utteranceRef.current) {
        window.speechSynthesis.resume();
        setPlaying(true);
        setPaused(false);
      } else {
        await speakText();
      }
    }
  }, [src, text, paused, speakText]);

  const pause = useCallback(() => {
    if (src && audioRef.current) {
      audioRef.current.pause();
    } else if (text && utteranceRef.current) {
      window.speechSynthesis.pause();
    }
    setPlaying(false);
    setPaused(true);
  }, [src, text]);

  const stop = useCallback(() => {
    if (src && audioRef.current) {
      audioRef.current.pause();
      audioRef.current.currentTime = 0;
    } else if (text) {
      window.speechSynthesis.cancel();
    }
    setPlaying(false);
    setPaused(false);
    setCurrentTime(0);
    setCharIndex(0);
  }, [src, text]);

  const seek = useCallback((time: number) => {
    if (src && audioRef.current) {
      audioRef.current.currentTime = time;
      setCurrentTime(time);
    }
  }, [src]);

  const setVolume = useCallback((v: number) => {
    if (audioRef.current) {
      audioRef.current.volume = Math.max(0, Math.min(1, v));
    }
    if (utteranceRef.current) {
      utteranceRef.current.volume = Math.max(0, Math.min(1, v));
    }
  }, []);

  const setRate = useCallback((r: number) => {
    if (audioRef.current) {
      audioRef.current.playbackRate = r;
    }
    if (utteranceRef.current) {
      utteranceRef.current.rate = r;
    }
  }, []);

  // Cleanup al desmontar
  useEffect(() => {
    return () => {
      if (audioRef.current) {
        audioRef.current.pause();
        audioRef.current.src = "";
      }
      if (window.speechSynthesis) {
        window.speechSynthesis.cancel();
      }
    };
  }, []);

  return {
    playing,
    paused,
    loading,
    error,
    currentTime,
    duration,
    charIndex,
    progress: duration > 0 ? (currentTime / duration) * 100 : 0,
    play,
    pause,
    stop,
    seek,
    setVolume,
    setRate,
    // Estado formateado
    formattedCurrentTime: formatTime(currentTime),
    formattedDuration: formatTime(duration),
  };
}

function formatTime(seconds: number): string {
  if (!seconds || isNaN(seconds)) return "0:00";
  const h = Math.floor(seconds / 3600);
  const m = Math.floor((seconds % 3600) / 60);
  const s = Math.floor(seconds % 60);
  if (h > 0) {
    return `${h}:${String(m).padStart(2, "0")}:${String(s).padStart(2, "0")}`;
  }
  return `${m}:${String(s).padStart(2, "0")}`;
}
